llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Perindopril, a prodrug ACE inhibitor with an ester and proline-like scaffold, has mean oral bioavailability of 65.6–95.1% in healthy volunteers, strongly supporting high F for the query prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Maraviroc has absolute oral bioavailability of 33% at a 300 mg dose in humans, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Encainide shows oral bioavailability of 20–30% in healthy subjects, at or above the threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Meperidine/pethidine has oral bioavailability of about 50% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "SAHA has absolute oral bioavailability of 43% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Labetalol has mean systemic availability of 33% after oral dosing, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Praziquantel has oral bioavailability of 27.2±5.4% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Actisomide has absolute oral bioavailability of 30–43% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Perindoprilat, the active diacid metabolite, showed 19% bioavailability after oral perindopril in young healthy subjects, below threshold; however, this measures the active metabolite, not the prodrug itself, and is outweighed by prodrug evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is fosinopril, a phosphinic acid ACE inhibitor prodrug. The closest prodrug analogue perindopril has high oral bioavailability (65–95%), and numerous other high-transfer analogues (maraviroc, encainide, pethidine, SAHA, labetalol, praziquantel, actisomide) all show F ≥20%. The only sub-threshold value is for the active diacid perindoprilat, not the prodrug, and is outweighed. Therefore predict high oral bioavailability (F≥20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for fosinopril (query) was provided; prediction relies on transferable analogues, especially perindopril prodrug.",
    "The effect of food, dose, and disease state on fosinopril bioavailability is not directly captured in the supplied evidence.",
    "The contradictory perindoprilat value reflects active metabolite exposure after prodrug administration, not the prodrug's own bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

